import charactersData from "../../characters-data.json";
import type { HistoricalCharacterId } from "./HistoricalCharacter.types";

export interface HistoricalCharacterDefinition {
  id: HistoricalCharacterId;
  name: string;
  aliases: readonly string[];
  image: string;
  imageV2: string;
}

// Generated by scripts/parse-scene-plan.mjs from the active project's scene-plan.md
// `## characters` block + each character's profile.json. Regenerate with
// `node scripts/parse-scene-plan.mjs` after switching projects or editing character data.
export const characterList: readonly HistoricalCharacterDefinition[] =
  charactersData.characters;

export const HISTORICAL_CHARACTERS: Record<
  string,
  HistoricalCharacterDefinition
> = Object.fromEntries(characterList.map((c) => [c.id, c]));

export function getCharacter(
  id: HistoricalCharacterId,
): HistoricalCharacterDefinition {
  const definition = HISTORICAL_CHARACTERS[id];
  if (!definition) {
    throw new Error(
      `Unknown character id "${id}" — check src/characters-data.json (regenerate with node scripts/parse-scene-plan.mjs).`,
    );
  }
  return definition;
}
